        function switchAuthTab(tab) {
            const loginForm = document.getElementById('login-form');
            const regForm = document.getElementById('register-form');
            const loginBtn = document.getElementById('tab-login-btn');
            const regBtn = document.getElementById('tab-register-btn');

            if (tab === 'login') {
                loginForm.classList.remove('hidden');
                regForm.classList.add('hidden');
                loginBtn.className = "flex-1 py-3 text-center font-bold border-b-2 border-spooky-orange text-spooky-orange";
                regBtn.className = "flex-1 py-3 text-center font-bold border-b-2 border-transparent text-gray-400 hover:text-white";
            } else {
                loginForm.classList.add('hidden');
                regForm.classList.remove('hidden');
                regBtn.className = "flex-1 py-3 text-center font-bold border-b-2 border-spooky-orange text-spooky-orange";
                loginBtn.className = "flex-1 py-3 text-center font-bold border-b-2 border-transparent text-gray-400 hover:text-white";
            }
        }

        function openAuthModal() {
            document.getElementById('auth-modal').classList.remove('hidden');
        }

        function closeModal(id) {
            document.getElementById(id).classList.add('hidden');
        }

        function handleRegister(e) {
            e.preventDefault();
            const username = document.getElementById('reg-username').value.trim();
            const pass = document.getElementById('reg-password').value;
            const confirmPass = document.getElementById('reg-confirm-password').value;
            const errDiv = document.getElementById('reg-error');

            if (!username) {
                errDiv.textContent = 'Введите никнейм';
                errDiv.classList.remove('hidden');
                return;
            }
            if (pass !== confirmPass) {
                errDiv.textContent = 'Пароли не совпадают!';
                errDiv.classList.remove('hidden');
                return;
            }

            const existing = localStorage.getItem(getUserStorageKey(username));
            if (existing) {
                errDiv.textContent = 'Никнейм уже занят!';
                errDiv.classList.remove('hidden');
                return;
            }

            // Create User
            currentUser = {
                username: username,
                password: pass, // Local demo auth
                pumpkins: 30,
                crystals: 50,
                inventory: [],
                lastFreeClaim: 0
            };
            
            saveUserData();
            localStorage.setItem('egg_drop_active_session', username);
            closeModal('auth-modal');
            updateUI();
        }

        function handleLogin(e) {
            e.preventDefault();
            const username = document.getElementById('login-username').value.trim();
            const pass = document.getElementById('login-password').value;
            const errDiv = document.getElementById('login-error');

            const rawData = localStorage.getItem(getUserStorageKey(username));
            if (!rawData) {
                errDiv.textContent = 'Пользователь не найден!';
                errDiv.classList.remove('hidden');
                return;
            }

            const data = JSON.parse(rawData);
            if (data.password && data.password !== pass) {
                errDiv.textContent = 'Неверный пароль!';
                errDiv.classList.remove('hidden');
                return;
            }

            currentUser = data;
            localStorage.setItem('egg_drop_active_session', username);
            closeModal('auth-modal');
            updateUI();
        }

        function logout() {
            localStorage.removeItem('egg_drop_active_session');
            currentUser = null;
            updateUI();
        }

        /* ==========================================================================
           5. ROULETTE & CASE OPENING ANIMATION
           ========================================================================== */
        
        function openCase(caseId) {
            if (!currentUser) {
                openAuthModal();
                return;
            }

            if (isSpinning) return;

            const caseData = CASES[caseId];
            if (!caseData) return;

            // Check currency
            if (caseData.costType === 'pumpkins') {
                if (currentUser.pumpkins < caseData.cost) {
                    alert('Недостаточно Тыкв! Воспользуйтесь кнопкой "+" вверху.');
                    return;
                }
                currentUser.pumpkins -= caseData.cost;
            } else if (caseData.costType === 'crystals') {
                if (currentUser.crystals < caseData.cost) {
                    alert('Недостаточно Кристаллов! Воспользуйтесь кнопкой "+" вверху.');
                    return;
                }
                currentUser.crystals -= caseData.cost;
            } else if (caseData.costType === 'free') {
                const now = Date.now();
                if (now - currentUser.lastFreeClaim < 24 * 60 * 60 * 1000) {
                    alert('Бесплатный кейс доступен раз в 24 часа!');
                    return;
                }
                currentUser.lastFreeClaim = now;
            }

            saveUserData();
            updateUI();

            // Prepare Roulette UI
            const modal = document.getElementById('roulette-modal');
            const track = document.getElementById('roulette-track');
            const resultArea = document.getElementById('roulette-result-area');
            const caseTitle = document.getElementById('roulette-case-title');

            caseTitle.textContent = caseData.name;
            resultArea.classList.add('opacity-0', 'scale-90');
            modal.classList.remove('hidden');
            isSpinning = true;

            // Generate 60 items for smooth spin reel
            track.replaceChildren(); // Clear existing children safely
            const totalCards = 60;
            const winningIndex = 48; // Target card index
            
            // Choose winner item using configured percentage chances when present.
            const hasConfiguredChances = caseData.pool.some(item => typeof item.chance === 'number');
            let winnerItem;
            if (hasConfiguredChances) {
                const totalChance = caseData.pool.reduce((sum, item) => sum + (typeof item.chance === 'number' ? item.chance : 0), 0);
                let roll = Math.random() * totalChance;
                winnerItem = caseData.pool[caseData.pool.length - 1];
                for (const item of caseData.pool) {
                    roll -= typeof item.chance === 'number' ? item.chance : 0;
                    if (roll < 0) { winnerItem = item; break; }
                }
            } else {
                winnerItem = caseData.pool[Math.floor(Math.random() * caseData.pool.length)];
            }

            const itemWidth = 120; // 120px width per card
            
            for (let i = 0; i < totalCards; i++) {
                let item = (i === winningIndex) ? winnerItem : caseData.pool[Math.floor(Math.random() * caseData.pool.length)];
                
                const card = document.createElement('div');
                card.className = `w-[110px] h-[130px] mx-[5px] flex-shrink-0 ${RARITY_COLORS[item.rarity].bg} border ${RARITY_COLORS[item.rarity].border} rounded-xl flex flex-col items-center justify-center p-2 text-center space-y-2 shadow-md`;
                card.innerHTML = `
                    ${item.image ? `<img src="${item.image}" alt="${item.name}" class="w-full h-[72px] object-contain rounded-md" />` : `<i class="fa-solid ${item.icon} text-3xl" style="color: ${item.color}"></i>`}
                    <span class="text-[10px] font-bold text-white line-clamp-2">${item.name}</span>
                    <span class="text-[9px] ${RARITY_COLORS[item.rarity].text} font-semibold">${RARITY_COLORS[item.rarity].name}</span>
                `;
                track.appendChild(card);
            }

            // Reset track position
            track.style.transition = 'none';
            track.style.transform = 'translateX(0px)';

            // Trigger Animation
            setTimeout(() => {
                const containerWidth = document.querySelector('.roulette-container').offsetWidth;
                // Target position offset to center the winning card under pointer
                const targetPos = (winningIndex * itemWidth) - (containerWidth / 2) + (itemWidth / 2) + (Math.random() * 40 - 20);

                track.style.transition = 'transform 6s cubic-bezier(0.1, 0.9, 0.1, 1)';
                track.style.transform = `translateX(-${targetPos}px)`;

                // Tick Sound Interval Simulator
                let tickCount = 0;
                const interval = setInterval(() => {
                    if (tickCount < 30) {
                        playSound('tick');
                        tickCount++;
                    } else {
                        clearInterval(interval);
                    }
                }, 150);

                // On Spin End
                setTimeout(() => {
                    isSpinning = false;
                    playSound('win');
                    
                    // Special cases award currency directly; ordinary cases award inventory items.
                    let rewardDescription;
                    if (caseData.id === 'free' && winnerItem.id === 'free_crystals_7') {
                        currentUser.crystals += 7;
                        rewardDescription = 'Получено: +7 кристаллов';
                    } else if (caseData.id === 'luckysecret_case') {
                        currentUser.crystals += 30;
                        rewardDescription = 'Получено: +30 кристаллов';
                    } else if (caseData.id === 'radomitsa_case') {
                        const pumpkinReward = Math.floor(Math.random() * 21) + 30;
                        currentUser.pumpkins += pumpkinReward;
                        rewardDescription = `Получено: +${pumpkinReward} тыкв`;
                    } else {
                        currentUser.inventory.push({
                            ...winnerItem,
                            obtainedAt: Date.now()
                        });
                        rewardDescription = `Продажная стоимость: ${winnerItem.price} ${winnerItem.currency === 'pumpkins' ? 'Тыкв' : 'Кристаллов'}`;
                    }
                    saveUserData();
                    updateUI();

                    // Display Winner Text
                    document.getElementById('won-item-name').textContent = caseData.id === 'radomitsa_case' ? 'Тыквы!' : winnerItem.name;
                    document.getElementById('won-item-name').style.color = winnerItem.color;
                    document.getElementById('won-item-value').textContent = rewardDescription;
                    
                    resultArea.classList.remove('opacity-0', 'scale-90');
                }, 6200);

            }, 50);
        }

        function closeRouletteModal() {
            if (isSpinning) return;
            document.getElementById('roulette-modal').classList.add('hidden');
        }

