        function renderInventory() {
            const grid = document.getElementById('inventory-grid');
            grid.replaceChildren(); // Clear existing children safely

            if (!currentUser || !currentUser.inventory || currentUser.inventory.length === 0) {
                grid.innerHTML = `
                    <div class="col-span-full py-12 text-center text-gray-500">
                        <i class="fa-solid fa-box-open text-4xl mb-2"></i>
                        <p>Ваш инвентарь пуст. Откройте кейсы!</p>
                    </div>
                `;
                return;
            }

            currentUser.inventory.forEach((item, index) => {
                const card = document.createElement('div');
                card.className = `bg-spooky-bg border ${RARITY_COLORS[item.rarity].border} rounded-xl p-3 flex flex-col items-center justify-between text-center relative group hover:scale-[1.02] transition`;
                
                card.innerHTML = `
                    <div class="space-y-1 my-2">
                        ${item.image ? `<img src="${item.image}" alt="${item.name}" class="w-full h-24 object-contain rounded-md" />` : `<i class="fa-solid ${item.icon} text-3xl" style="color: ${item.color}"></i>`}
                        <div class="text-xs font-bold text-white leading-tight">${item.name}</div>
                        <div class="text-[10px] ${RARITY_COLORS[item.rarity].text}">${RARITY_COLORS[item.rarity].name}</div>
                    </div>
                    <button onclick="sellItem(${index})" class="w-full mt-2 py-1 bg-red-950/40 hover:bg-red-900/60 border border-red-500/30 text-red-400 text-xs rounded-lg transition flex items-center justify-center gap-1">
                        <span>Продать за ${item.price}</span>
                        <i class="fa-solid ${item.currency === 'pumpkins' ? 'fa-pumpkin text-spooky-orange' : 'fa-gem text-cyan-400'}"></i>
                    </button>
                `;
                grid.appendChild(card);
            });
        }

        function sellItem(index) {
            if (!currentUser || !currentUser.inventory[index]) return;

            const item = currentUser.inventory[index];
            if (item.currency === 'pumpkins') {
                currentUser.pumpkins += item.price;
            } else {
                currentUser.crystals += item.price;
            }

            currentUser.inventory.splice(index, 1);
            saveUserData();
            updateUI();
            renderInventory();
        }

        /* ==========================================================================
           7. UI HELPERS & TIMERS
           ========================================================================== */
        
        function updateUI() {
            const profileArea = document.getElementById('user-profile-area');

            if (currentUser) {
                // Display user info
                document.getElementById('balance-pumpkins').textContent = currentUser.pumpkins;
                document.getElementById('balance-crystals').textContent = currentUser.crystals;
                document.getElementById('inventory-count-badge').textContent = currentUser.inventory ? currentUser.inventory.length : 0;

                profileArea.innerHTML = `
                    <div class="flex items-center gap-2 bg-spooky-card border border-spooky-cardBorder px-3 py-1.5 rounded-xl">
                        <i class="fa-solid fa-user-ninja text-spooky-purple"></i>
                        <span class="text-sm font-bold text-white">${currentUser.username}</span>
                        <button onclick="logout()" class="ml-2 text-xs text-gray-400 hover:text-red-400" title="Выйти">
                            <i class="fa-solid fa-right-from-bracket"></i>
                        </button>
                    </div>
                `;
            } else {
                document.getElementById('balance-pumpkins').textContent = '0';
                document.getElementById('balance-crystals').textContent = '0';
                document.getElementById('inventory-count-badge').textContent = '0';

                profileArea.innerHTML = `
                    <button onclick="openAuthModal()" class="px-4 py-2 bg-spooky-orange hover:bg-orange-500 text-white font-bold rounded-xl text-sm transition shadow-lg shadow-orange-950/40">
                        Войти / Регистрация
                    </button>
                `;
            }

            checkFreeCaseAvailability();
        }

        function openBonusModal() {
            if (!currentUser) {
                openAuthModal();
                return;
            }
            document.getElementById('bonus-modal').classList.remove('hidden');
        }

        function addCurrency(pumpkins, crystals) {
            if (!currentUser) return;
            currentUser.pumpkins += pumpkins;
            currentUser.crystals += crystals;
            saveUserData();
            updateUI();
            closeModal('bonus-modal');
        }


        
        function redeemPromoCode() {
            const input = document.getElementById('promo-code-input');
            const message = document.getElementById('promo-code-message');
            const rawCode = input.value.trim();
            if (!currentUser) {
                message.className = 'text-sm text-center min-h-5 text-red-400';
                message.textContent = 'Сначала войди в аккаунт, чтобы активировать промокод.';
                openAuthModal();
                return;
            }
            if (!rawCode) {
                message.className = 'text-sm text-center min-h-5 text-red-400';
                message.textContent = 'Введи промокод.';
                return;
            }
            const codeKey = rawCode.toLocaleUpperCase('ru-RU');
            const codes = {
                'LUCKYSECRET': { crystals: 150, pumpkins: 0, label: '+150 кристаллов' },
                'RELEASE26': { crystals: 150, pumpkins: 0, label: '+150 кристаллов', maxActivations: 700 },
                'ХЭЛЛОУИН2026': { crystals: 0, pumpkins: 100, label: '+100 тыкв' }
            };
            if (!codes[codeKey]) {
                message.className = 'text-sm text-center min-h-5 text-red-400';
                message.textContent = 'Такого промокода нет.';
                return;
            }
            if (!Array.isArray(currentUser.redeemedCodes)) currentUser.redeemedCodes = [];
            if (currentUser.redeemedCodes.includes(codeKey)) {
                message.className = 'text-sm text-center min-h-5 text-yellow-400';
                message.textContent = 'Ты уже использовал этот промокод.';
                return;
            }
            const reward = codes[codeKey];
            if (reward.maxActivations) {
                const countKey = 'promo_activations_' + codeKey;
                const activations = Number(localStorage.getItem(countKey) || '0');
                if (activations >= reward.maxActivations) {
                    message.className = 'text-sm text-center min-h-5 text-red-400';
                    message.textContent = 'Лимит активаций этого промокода исчерпан.';
                    return;
                }
                localStorage.setItem(countKey, String(activations + 1));
            }
            currentUser.crystals += reward.crystals;
            currentUser.pumpkins += reward.pumpkins;
            currentUser.redeemedCodes.push(codeKey);
            saveUserData();
            updateUI();
            message.className = 'text-sm text-center min-h-5 text-green-400';
            message.textContent = `Успешно! Получено: ${reward.label}.`;
            input.value = '';
        }

        function checkFreeCaseAvailability() {
            const statusLabel = document.getElementById('free-case-timer-status');
            const freeBtn = document.getElementById('btn-claim-free');

            if (!currentUser) {
                statusLabel.textContent = "Требуется авторизация";
                return;
            }

            const now = Date.now();
            const diff = now - (currentUser.lastFreeClaim || 0);
            const cooldown = 24 * 60 * 60 * 1000;

            if (diff < cooldown) {
                const remaining = cooldown - diff;
                const hours = Math.floor(remaining / (1000 * 60 * 60));
                const minutes = Math.floor((remaining % (1000 * 60 * 60)) / (1000 * 60));
                statusLabel.textContent = `Доступно через ${hours} ч. ${minutes} мин.`;
                freeBtn.classList.add('opacity-50', 'cursor-not-allowed');
            } else {
                statusLabel.textContent = "Доступно прямо сейчас!";
                freeBtn.classList.remove('opacity-50', 'cursor-not-allowed');
            }
        }

        // 20-Day Halloween Countdown Timer Simulation
        function initEventTimer() {
            const timerElem = document.getElementById('event-timer');
            // 20 days target
            let endTime = localStorage.getItem('egg_drop_event_end');
            if (!endTime) {
                endTime = Date.now() + (20 * 24 * 60 * 60 * 1000);
                localStorage.setItem('egg_drop_event_end', endTime);
            } else {
                endTime = parseInt(endTime);
            }

            setInterval(() => {
                const now = Date.now();
                const dist = endTime - now;
                if (dist < 0) {
                    timerElem.textContent = "Ивент Завершен";
                    return;
                }

                const days = Math.floor(dist / (1000 * 60 * 60 * 24));
                const hours = Math.floor((dist % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
                const minutes = Math.floor((dist % (1000 * 60 * 60)) / (1000 * 60));
                const seconds = Math.floor((dist % (1000 * 60)) / 1000);

                timerElem.textContent = `${days} дн. ${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
            }, 1000);
        }
